+.pattern-button:hover{color:var(--text);background:#ffffff08}
+.pattern-button.selected{background:#34372a;color:var(--lime);box-shadow:inset 0 0 0 1px #d2f36b20}
+.pattern-button:focus-visible{outline:2px solid var(--lime);outline-offset:2px;position:relative;z-index:1}
+.pattern-guide{margin:0 0 14px;padding:10px 11px 9px;border:1px solid #ffffff0b;border-radius:8px;background:#141519}
