+.pattern-step{padding:6px 3px;border:1px solid #ffffff0d;border-radius:5px;color:#81828a;text-align:center;font:8px var(--mono);white-space:nowrap;transition:color .18s,border-color .18s,background .18s}
+.pattern-step.active{border-color:#d2f36b70;background:#d2f36b12;color:var(--lime);box-shadow:0 0 12px #d2f36b10}
